-- 801.csv レーザ加工品 m_product 取込SQL
-- 条件: 既存product_codeはスキップ / 品名空は「なし」
-- 固定値: category=SINGLE, unit=個, line=L0801, process=0801, management_unit=DAY,
--         is_line_final_product=1, is_active=1, is_final_product=0, is_virtual_set=0, is_phantom=0, order_lot_multiple=1
START TRANSACTION;

INSERT INTO m_product (
  product_code,
  product_name,
  product_name_halfwidth,
  category,
  unit,
  standard_lt_days,
  image_url,
  line_id,
  process_id,
  management_unit,
  self_lt_days,
  is_final_product,
  is_line_final_product,
  is_phantom,
  is_virtual_set,
  order_lot_min,
  order_lot_multiple,
  model_name,
  product_group_id,
  used_container_id,
  capacity,
  is_active,
  created_at,
  updated_at
)
SELECT
  '3109879',
  'ﾌﾞﾗｹｯﾄ',
  'ﾌﾞﾗｹｯﾄ',
  'SINGLE',
  '個',
  NULL,
  NULL,
  (SELECT id FROM m_line WHERE line_code = 'L0801' LIMIT 1),
  (SELECT id FROM m_process WHERE process_code = '0801' LIMIT 1),
  'DAY',
  NULL,
  0,
  1,
  0,
  0,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  1,
  NOW(),
  NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM m_product p WHERE p.product_code = '3109879'
);
